export function orderPayload(amountCents: number): string {
  if (typeof amountCents !== 'number' || !Number.isInteger(amountCents) || amountCents < 0) throw new RangeError('amountCents must be a nonnegative integer');
  return JSON.stringify({ amountCents: String(amountCents) });
}

files.src/consumer.ts:
export function isLargeOrder(order: { amountCents: unknown }): boolean {
  if (typeof order.amountCents !== 'number' || !Number.isInteger(order.amountCents) || order.amountCents < 0) throw new TypeError('amountCents must be a nonnegative integer');
  return order.amountCents >= 10000;
}

